]

# Show demo input shapes with their bounding boxes
def get_bboxes(grid, color):
    positions = set()
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] == color:
                positions.add((r,c))
    if positions:
        rows = [p[0] for p in positions]
        cols = [p[1] for p in positions]
        return {
            'min_row': min(rows), 'max_row': max(rows),
            'min_col': min(cols), 'max_col': max(cols),
            'height': max(rows) - min(rows) + 1,
            'width': max(cols) - min(cols) + 1,
            'center': (sum(rows)/len(rows), sum(cols)/len(cols)),
            'count': len(positions),
            'positions': sorted(positions)
        }

print("Demo INPUT shapes:")
for color in [1,2,3,4]:
    b = get_bboxes(demo_input, color)
    print(f"  Color {color}: count={b['count']}, bbox=({b['min_row']}-{b['max_row']},{b['min_col']}-{b['max_col']})")

print("\nDemo OUTPUT shapes:")
for color in [1,2,3,4]:
